// Final footage capture. Real dashboard, real runs - nothing here draws UI.
//
// Output (all gitignored, regenerated by re-running this):
//   capture/public/shots/<name>.png   2x (desktop) / 3x (mobile) screenshots
//   capture/public/layout.json        per-shot CSS size + element boxes in
//                                     page coordinates, for camera targets
//
// Motion (scrolling, the cursor, the freeze-and-circle) is applied later in
// Remotion over these frames; the frames themselves are untouched pixels.
//
//   node scripts/capture.mjs            # everything
//   node scripts/capture.mjs desktop    # one half
import { chromium } from "playwright";
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { BASE, assertThisApp } from "./guard.mjs";

const OUT = "capture/public/shots";
const LAYOUT = "capture/public/layout.json";
mkdirSync(OUT, { recursive: true });
const layout = existsSync(LAYOUT) ? JSON.parse(readFileSync(LAYOUT, "utf8")) : {};
const state = JSON.parse(readFileSync("capture/state.json", "utf8"));
const only = process.argv[2];
// Resume point for a desktop capture that stopped part-way: FROM=ask.
const ORDER = ["ingest", "ask", "after-keep"];
const reached = (step) => ORDER.indexOf(step) >= ORDER.indexOf(process.env.FROM ?? "ingest");

// Runs filmed. 608 is an existing demo_full.csv run (synthetic, seeded);
// 646-651 come from scripts/seed_demo_runs.py; 385/384 are existing runs of
// public Kaggle ad-conversion and crop-production exports.
const R = {
  showcase: "fda0f658-6b52-4332-9bde-c48d183c6eab", // #608
  clean: state.clean.run_id,
  renamed: state.renamed.run_id,
  dollar: state.dollar.run_id,
  sql: state.sql.run_id,
  marketing: "617e22e1-27c5-48e6-92c5-6fe3ab3dfcf8", // #385
  agriculture: "946c7c4d-e2b4-4579-8fa8-aa9025b1f3a1", // #384
};

async function settle(page, ms = 1500) {
  await page.waitForLoadState("networkidle").catch(() => {});
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(ms);
}

/** Boxes (page coords, CSS px) of the smallest element containing `text`,
 *  optionally widened to its closest ancestor matching `closest`. */
async function boxes(page, specs) {
  return page.evaluate((specs) => {
    const out = {};
    const all = [...document.querySelectorAll("body *")];
    for (const [key, s] of Object.entries(specs)) {
      const hits = all.filter((el) => el.textContent && el.textContent.includes(s.text) && el.offsetParent !== null);
      // smallest = the hit with no hit inside it
      let el = hits.find((h) => !hits.some((o) => o !== h && h.contains(o)));
      if (s.nth) el = hits.filter((h) => !hits.some((o) => o !== h && h.contains(o)))[s.nth];
      if (!el) continue;
      if (s.closest) el = el.closest(s.closest) ?? el;
      const r = el.getBoundingClientRect();
      out[key] = { x: Math.round(r.x + scrollX), y: Math.round(r.y + scrollY), w: Math.round(r.width), h: Math.round(r.height) };
    }
    return out;
  }, specs);
}

async function shot(page, name, { full = true, specs = {} } = {}) {
  const size = await page.evaluate(() => ({ w: document.documentElement.scrollWidth, h: document.documentElement.scrollHeight, sy: scrollY }));
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: full });
  const b = await boxes(page, specs);
  // A viewport shot's boxes are relative to what was on screen.
  if (!full) for (const v of Object.values(b)) v.y -= size.sy;
  const vp = page.viewportSize();
  layout[name] = { w: full ? size.w : vp.width, h: full ? size.h : vp.height, boxes: b };
  console.log(`  ${name}  ${layout[name].w}x${layout[name].h}  boxes: ${Object.keys(b).join(", ") || "-"}`);
}

const approvalSpecs = {
  card: { text: "post-condition failed", closest: "div.rounded-md, div.rounded-lg, div.border" },
  diagnosis: { text: "Diagnosis:", closest: "p, div" },
  gate: { text: "post-condition failed", closest: "p, div" },
  approve: { text: "Approve" },
  keep: { text: "Keep data as-is" },
  accept: { text: "Accept as new baseline" },
  discard: { text: "Discard run (permanent)" },
  warnings: { text: "Connector warnings", closest: "section, .panel" },
  ack: { text: "Acknowledge" },
};

async function setTheme(page, theme) {
  await page.selectOption("#theme-select", theme);
  await page.waitForTimeout(600);
}

// ------------------------------------------------------------- desktop --
async function desktop(browser) {
  console.log("desktop 1440x900 @2x");
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2, acceptDownloads: true });
  const page = await ctx.newPage();
  await assertThisApp(page);
  await setTheme(page, "default");

  if (reached("ingest")) {
  // 1. Ingest: the three connector types on the register form, then a real
  //    upload + ingest with the elapsed-time line on screen.
  await page.goto(`${BASE}/sources`);
  await settle(page);
  await shot(page, "sources-top", { full: false, specs: { upload: { text: "Upload a CSV or Excel file", closest: ".panel, section, div" }, register: { text: "Register a source another way" } } });
  const typeSelect = page.locator("select").filter({ has: page.locator('option[value="sql"]') }).first();
  const cfg = page.locator("textarea").first();
  await typeSelect.selectOption("sql");
  await cfg.fill('{"connection_string_env": "ADIP_DEMO_SQL_URL", "query": "select * from orders"}');
  await page.waitForTimeout(400);
  await shot(page, "sources-sql", { full: false, specs: { form: { text: "Register a source another way" } } });
  await typeSelect.selectOption("api");
  await cfg.fill('{"url": "http://127.0.0.1:8765/orders.json"}');
  await page.waitForTimeout(400);
  await shot(page, "sources-api", { full: false, specs: { form: { text: "Register a source another way" } } });
  await typeSelect.selectOption("file");

  await page.locator("#sources-upload-file").setInputFiles("capture/data/orders_upload.csv");
  await page.waitForTimeout(400);
  await shot(page, "sources-chosen", { full: false, specs: { uploadBtn: { text: "Upload", closest: "button" } } });
  await page.getByRole("button", { name: "Upload", exact: true }).click();
  const registered = page.locator("text=Uploaded and registered:").first();
  await registered.waitFor({ timeout: 30_000 });
  const sourceId = (await registered.locator("code").textContent())?.trim();
  const row = page.locator("tr", { has: page.locator(`code:text-is("${sourceId}")`) });
  await row.scrollIntoViewIfNeeded();
  await page.evaluate(() => scrollBy(0, 200));
  await page.waitForTimeout(500);
  await shot(page, "ingest-0", { full: false, specs: { row: { text: sourceId, closest: "tr" } } });
  await row.getByRole("button", { name: "Ingest", exact: true }).click();
  for (let i = 1; i <= 3; i++) {
    await page.waitForTimeout(1500);
    await shot(page, `ingest-${i}`, { full: false, specs: { row: { text: sourceId, closest: "tr" } } });
  }
  await row.locator("text=/Ingest finished:/").waitFor({ timeout: 300_000 });
  await page.waitForTimeout(800);
  await shot(page, "ingest-done", { full: false, specs: { row: { text: sourceId, closest: "tr" } } });

  // 2. Self-healing: the kept fix (#647) and the revert (#648) on Audit.
  await page.goto(`${BASE}/audit?run=${R.renamed}`);
  await page.getByRole("heading", { name: /Timeline/ }).waitFor({ timeout: 60_000 });
  await settle(page);
  await shot(page, "audit-kept", {
    specs: {
      timeline: { text: "Timeline - nodes visited" , closest: "section, .panel, div.rounded-md" },
      egress: { text: "Egress - what left this machine", closest: "section, .panel, div.rounded-md" },
      masked: { text: "customer_email", nth: 1 },
      events: { text: "Validation events", closest: "section, .panel, div.rounded-md" },
      autofixed: { text: "auto_fixed", closest: "tr" },
    },
  });
  await page.goto(`${BASE}/audit?run=${R.dollar}`);
  await page.getByRole("heading", { name: /Timeline/ }).waitFor({ timeout: 60_000 });
  await settle(page);
  await shot(page, "audit-reverted", {
    specs: {
      events: { text: "Validation events", closest: "section, .panel, div.rounded-md" },
      reverted: { text: "(reverted)", closest: "tr" },
      postcond: { text: "post-condition failed" },
    },
  });

  // 3. The approval queue, pending: four decisions + acknowledge.
  await page.goto(`${BASE}/approvals`);
  await page.getByRole("heading", { name: "Approvals", exact: true }).waitFor();
  await settle(page, 2500);
  await shot(page, "approvals", { specs: approvalSpecs });

  // 4. Insights on the showcase run: summary + grounded narrative + charts.
  await page.goto(`${BASE}/reports?run=${R.showcase}`);
  await page.getByRole("heading", { name: "Narrative" }).waitFor({ timeout: 60_000 });
  await settle(page, 3500);
  await shot(page, "reports", {
    specs: {
      summary: { text: "Written from this run's stored results", closest: "section, .panel, div.rounded-md" },
      writtenBy: { text: "written by a model" },
      caveat: { text: "Data quality context", nth: 1, closest: "div.rounded-md, div.border" },
      narrative: { text: "Revenue moves together", closest: "div, p" },
      claimLink: { text: "(see claim-1)" },
      charts: { text: "revenue - distribution", closest: "div.rounded-md, div.border" },
      claims: { text: "grounded claims" },
    },
  });
  await page.goto(`${BASE}/reports?run=${R.renamed}`);
  await page.getByRole("heading", { name: "Narrative" }).waitFor({ timeout: 60_000 });
  await settle(page, 3000);
  await shot(page, "reports-orders", { specs: { privacy: { text: "Detected deterministically at ingest", closest: "section, .panel, div.rounded-md" }, summary: { text: "Written from this run's stored results", closest: "section, .panel, div.rounded-md" } } });

  await page.goto(`${BASE}/analytics?run=${R.showcase}`);
  await page.getByRole("heading", { name: /ABC \/ Pareto/ }).waitFor({ timeout: 60_000 });
  await settle(page, 3000);
  await shot(page, "analytics", { specs: { notApplicable: { text: "Not applicable to this data", closest: "section, .panel, div.rounded-md" }, pareto: { text: "ABC / Pareto concentration", closest: "section, .panel, div.rounded-md" }, roles: { text: "Roles detected" } } });

  }
  if (reached("ask")) {
  // Ask: one real question -> generated code -> result (one model call),
  // against the SQL-connector run: its table is unchanged since ingest, so
  // the run's data rebuilds exactly (a file source re-reads its file).
  await page.goto(`${BASE}/ask?run=${R.sql}`);
  await page.getByRole("heading", { name: "Ask", exact: true }).waitFor();
  await settle(page);
  const q = "what is the total quantity by category?";
  await page.locator("textarea").first().fill(q);
  await page.waitForTimeout(300);
  await shot(page, "ask-typed", { full: false, specs: { question: { text: "Question", closest: "div" }, askBtn: { text: "Ask", nth: 2 } } });
  await page.getByRole("button", { name: "Ask", exact: true }).click();
  await page.getByRole("heading", { name: "Generated code" }).waitFor({ timeout: 180_000 });
  await settle(page, 1500);
  await shot(page, "ask-result", { specs: { code: { text: "Generated code", closest: "div" }, result: { text: "Result", closest: "div" } } });

  // Predict: the forecast against its naive baseline (training, one intent call).
  await page.goto(`${BASE}/predict?run=${R.showcase}`);
  await page.getByRole("heading", { name: "Predict", exact: true }).waitFor();
  await settle(page);
  await page.locator("textarea").first().fill("forecast monthly revenue");
  await page.getByRole("button", { name: "Predict", exact: true }).click();
  await page.getByText("Out-of-sample performance").first().waitFor({ timeout: 300_000 });
  await settle(page, 3000);
  await shot(page, "predict-result", { specs: { perf: { text: "Out-of-sample performance", closest: "section, .panel, div.rounded-md" }, chart: { text: "Forecast chart", closest: "section, .panel, div.rounded-md" } } });

  // Compare: the clean baseline run vs the run whose rename was auto-fixed.
  await page.goto(`${BASE}/compare`);
  await page.getByPlaceholder("earlier run (e.g. 17)").fill(String(state.clean.run_number));
  await page.getByPlaceholder("later run (e.g. 18)").fill(String(state.renamed.run_number));
  await page.getByRole("button", { name: "Compare", exact: true }).click();
  await page.getByText("Runs compared").first().waitFor({ timeout: 60_000 });
  await settle(page, 2500);
  await shot(page, "compare", { specs: { runs: { text: "Runs compared", closest: "section, .panel, div.rounded-md" } } });

  // Domain packs.
  await page.goto(`${BASE}/marketing?run=${R.marketing}`);
  await page.getByText("Key values").first().waitFor({ timeout: 60_000 });
  await settle(page, 2500);
  await shot(page, "marketing", { specs: { keys: { text: "Key values", closest: "section, .panel, div.rounded-md" }, budget: { text: "Where the budget goes", closest: "section, .panel, div.rounded-md" } } });
  await page.goto(`${BASE}/agriculture?run=${R.agriculture}`);
  await page.getByText("Key values").first().waitFor({ timeout: 60_000 });
  await settle(page, 2500);
  await shot(page, "agriculture", { specs: { keys: { text: "Key values", closest: "section, .panel, div.rounded-md" } } });

  // Export: build the deck, then click the download.
  await page.goto(`${BASE}/export?run=${R.showcase}`);
  await page.getByRole("heading", { name: "Export", level: 1 }).waitFor();
  await settle(page, 2000);
  const build = page.getByRole("button", { name: /Build deck|Rebuild deck/ });
  await shot(page, "export-before", { full: false, specs: { contents: { text: "What this deck will contain", closest: "section, .panel, div.rounded-md" }, build: { text: "Build deck" } } });
  if (await build.isVisible().catch(() => false)) await build.click();
  const download = page.getByRole("link", { name: /Download \.pptx/ });
  await download.waitFor({ timeout: 180_000 });
  await settle(page, 800);
  await shot(page, "export-ready", { full: false, specs: { download: { text: "Download .pptx" } } });
  const [dl] = await Promise.all([page.waitForEvent("download"), download.click()]);
  await page.waitForTimeout(800);
  await shot(page, "export-clicked", { full: false, specs: { download: { text: "Download .pptx" } } });
  console.log(`  deck downloaded: ${dl.suggestedFilename()}`);

  // Theme flashes: the same report in the other two themes.
  for (const theme of ["dark", "aurora"]) {
    await page.goto(`${BASE}/reports?run=${R.showcase}`);
    await page.getByRole("heading", { name: "Narrative" }).waitFor({ timeout: 60_000 });
    await setTheme(page, theme);
    await settle(page, 3000);
    await shot(page, `theme-${theme}`, { full: false });
  }
  await setTheme(page, "default");
  await page.goto(`${BASE}/reports?run=${R.showcase}`);
  await settle(page, 3000);
  await shot(page, "theme-default", { full: false });

  // LAST, because they change state: a person resolves the two items the
  // seed created (never the pre-existing escalation from run #2).
  await page.goto(`${BASE}/approvals`);
  await settle(page, 2500);
  const card = page.locator("div").filter({ hasText: "post-condition failed" }).filter({ has: page.getByRole("button", { name: "Keep data as-is" }) }).last();
  await card.getByRole("button", { name: "Keep data as-is", exact: true }).hover();
  await page.waitForTimeout(400);
  await shot(page, "approvals-hover-keep", { full: false, specs: { keep: { text: "Keep data as-is" } } });
  await card.getByRole("button", { name: "Keep data as-is", exact: true }).click();
  await page.waitForTimeout(4000);
  }
  if (reached("after-keep")) {
  await page.goto(`${BASE}/approvals`);
  await settle(page, 2500);
  await shot(page, "approvals-after-keep", { specs: approvalSpecs });
  const ack = page.getByRole("button", { name: "Acknowledge", exact: true }).first();
  await ack.scrollIntoViewIfNeeded();
  await ack.hover();
  await page.waitForTimeout(400);
  await shot(page, "approvals-hover-ack", { full: false, specs: { ack: { text: "Acknowledge" } } });
  await ack.click();
  await page.waitForTimeout(2500);
  await shot(page, "approvals-after-ack", { full: false, specs: { warnings: { text: "Connector warnings", closest: "section, .panel" } } });
  }

  await ctx.close();
}

// -------------------------------------------------------------- mobile --
async function mobile(browser) {
  console.log("mobile 390x844 @3x");
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 3, isMobile: true, hasTouch: true });
  const page = await ctx.newPage();
  await assertThisApp(page);
  await setTheme(page, "default").catch(() => {});
  const pages = [
    ["m-audit-kept", `/audit?run=${R.renamed}`, { autofixed: { text: "auto_fixed", closest: "tr" }, egress: { text: "Egress - what left this machine" }, events: { text: "Validation events" } }],
    ["m-audit-reverted", `/audit?run=${R.dollar}`, { reverted: { text: "(reverted)", closest: "tr" }, events: { text: "Validation events" }, postcond: { text: "post-condition failed" } }],
    ["m-reports", `/reports?run=${R.showcase}`, { summary: { text: "Written from this run's stored results" }, narrative: { text: "Revenue moves together" }, charts: { text: "revenue - distribution" } }],
    ["m-approvals", `/approvals`, { ack: { text: "Acknowledge" }, keep: { text: "Keep data as-is" } }],
    ["m-analytics", `/analytics?run=${R.showcase}`, { pareto: { text: "ABC / Pareto concentration" } }],
  ];
  for (const [name, path, specs] of pages) {
    await page.goto(BASE + path);
    await settle(page, 3500);
    await shot(page, name, { specs });
  }
  await ctx.close();
}

const browser = await chromium.launch();
try {
  // Mobile first: desktop ends by resolving the approvals mobile films pending.
  if (!only || only === "mobile") await mobile(browser);
  if (!only || only === "desktop") await desktop(browser);
} finally {
  writeFileSync(LAYOUT, JSON.stringify(layout, null, 2));
  await browser.close();
}
